/**
 * Service Worker Template for Force Updates
 * 
 * This template is for reference. The actual service worker is generated by VitePWA.
 * 
 * To add custom logic to the generated service worker, add this to your vite.config.mjs:
 * 
 * VitePWA({
 *   registerType: 'prompt',
 *   // ... other options
 *   injectManifest: {
 *     swSrc: 'public/sw-template.js',
 *     swDest: 'public/sw.js',
 *   },
 *   // ... rest of config
 * })
 * 
 * This would allow custom service worker logic for force update handling.
 */

self.addEventListener('install', (event) => {
  console.log('Service Worker installing...')
  self.skipWaiting() // Activate immediately for force updates
})

self.addEventListener('activate', (event) => {
  console.log('Service Worker activating...')
  event.waitUntil(clients.claim()) // Take control of all pages immediately
})

// Listen for skip waiting command
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting()
  }
})

// Force update support
self.addEventListener('fetch', (event) => {
  // Add custom caching strategies here
  event.respondWith(
    caches.match(event.request).then((response) => {
      return response || fetch(event.request)
    })
  )
})

